import heapq, math, random

def reservoir_sample_r(stream, k: int, rng: random.Random) -> list:
    reservoir = []
    for i, item in enumerate(stream, start=1):
        if i <= k:
            reservoir.append(item)
        else:
            j = rng.randint(1, i)
            if j <= k:
                reservoir[j - 1] = item
    return reservoir

def weighted_reservoir_key(weight: float, rng: random.Random) -> float:
    """Log-space Efraimidis-Spirakis key prevents u^(1/w) underflow & merges cleanly across shards."""
    u = max(rng.random(), 1e-18)
    return math.log(u) / weight
